/// <summary>
/// Event handler class for PurchAgreement form
/// </summary>
public class AVAPurchAgreementFrm_EventHandler
{   

}

Method.Source:
/// <summary>
/// AVAMarkupTrans_HeadingPurchAgreement
/// </summary>
/// <param name="_sender">FormControl</param>
/// <param name="_e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(PurchAgreement, AVAMarkupTrans_HeadingPurchAgreement), FormControlEventType::Clicked)]
public static void AVAMarkupTrans_HeadingPurchAgreement_OnClicked(FormControl _sender, FormControlEventArgs _e)
{
    MenuFunction    menuFunction;
    Args            args = new Args();
    boolean avaBPCheck;

    if(_e)
    {
        avaBPCheck = true;
    }

    FormDataSource          purchAgreementHeaderDS = _sender.formRun().dataSource('PurchAgreementHeader');
    PurchAgreementHeader    purchagreementHeader, newPurchAgreementHeader;        

    if (purchAgreementHeaderDS)
    {
        purchagreementHeader = purchAgreementHeaderDS.cursor();
        select firstonly newPurchAgreementHeader
            where   newPurchAgreementHeader.PurchNumberSequence == purchagreementHeader.PurchNumberSequence
                 && newPurchAgreementHeader.BuyingLegalEntity == purchagreementHeader.BuyingLegalEntity;

        args.record(newPurchAgreementHeader);

        menuFunction = new MenuFunction(menuItemDisplayStr(AVAMarkupTrans_HeadingPurchAgreement), MenuItemType::Display);

        if (menuFunction && menuFunction.checkAccessRights())
        {

            menuFunction.run(args);
        }
    }
}

/// <summary>
/// AVAMarkupTrans_LinePurchAgreement
/// </summary>
/// <param name="_sender">FormControl</param>
/// <param name="_e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(PurchAgreement, AVAMarkupTrans_LinePurchAgreement), FormControlEventType::Clicked)]
public static void AVAMarkupTrans_LinePurchAgreement_OnClicked(FormControl _sender, FormControlEventArgs _e)
{
    MenuFunction    menuFunction;
    Args            args = new Args();
    boolean avaBPCheck;

    if(_e)
    {
        avaBPCheck = true;
    }

    FormDataSource  avaAgreementLineDS = _sender.formRun().dataSource('ALine');
    AgreementLine   avaAgreementLine, newAgreementLine;

    if (avaAgreementLineDS)
    {
        avaAgreementLine = avaAgreementLineDS.cursor();
        select firstonly newAgreementLine
            where newAgreementLine.Agreement == avaAgreementLine.Agreement
               && newAgreementLine.LineNumber == avaAgreementLine.LineNumber;

        args.record(newAgreementLine);

        menuFunction = new MenuFunction(menuItemDisplayStr(AVAMarkupTrans_LinePurchAgreement), MenuItemType::Display);

        if (menuFunction && menuFunction.checkAccessRights())
        {

            menuFunction.run(args);
        }
    }
}
